{
  "ok": false,
  "name": "place_callout",
  "error": {
    "type": "invalid_params",
    "message": "'position' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "target": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "an explicit point for the leader to point at, in the callout's own space (paper inches on a sheet); prefer target_entity or target_anchor, which cannot miss"
        },
        "target_entity": {
          "type": "string",
          "minLength": 1,
          "description": "what to point at, by id (find_entities and hit_test return them; reference elements are 'BASE:LN-017'). The engine computes a point on it, so a curve is aimed at correctly. On a sheet it may be a model or referenced entity: the tip lands where the viewport shows it. Give exactly one of target / target_entity / target_anchor."
        },
        "at": {
          "description": "where along target_entity the leader TIP goes: start|mid|end or a fraction 0-1 (default mid) -- not where the text goes, which is position. From a sheet it runs along the part of the entity that sheet shows, so mid is always a point the reader can see"
        },
        "target_anchor": {
          "type": [
            "string",
            "number",
            "object"
          ],
          "description": "a station, offset or named point of an alignment to point at: '87+41.62@19.75L', 'PC-2', {station, offset}. There is no entity at a station, so this is how a station-and-offset callout is aimed"
        },
        "alignment": {
          "type": "string",
          "minLength": 1,
          "description": "the alignment target_anchor is on; a referenced one is 'BASE:RTE-7' (read, not owned -- the callout carries no anchor). Defaults to the document's only alignment"
        },
        "viewport": {
          "type": "string",
          "minLength": 1,
          "description": "on a sheet, the viewport to see the target through (default: the first one that shows it)"
        },
        "position": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "where the text sits, clear of the geometry, in the callout's own space. The text reads away from the target: when the target is to the left, the text starts here and runs right (left-justified); when it is to the right, the text ends here (right-justified). Vertically it is centred on this point, and the landing runs from here back toward the target"
        },
        "content": {
          "type": "string",
          "minLength": 1,
          "description": "the callout's text; \\n starts a new line"
        },
        "height": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "text height in space units (feet in model, inches on sheets); defaults to the annotation scale in model space, 0.10 in on a sheet"
        },
        "landing": {
          "type": "number",
          "minimum": 0,
          "description": "horizontal shoulder at the text (default 2.5 x height; 0 for none)"
        },
        "arrow": {
          "type": "boolean",
          "description": "arrowhead at the target (default true)"
        },
        "arrow_size": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "arrowhead length (default: the text height)"
        },
        "style": {
          "type": "string",
          "minLength": 1
        }
      },
      "required": [
        "space",
        "position",
        "content"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "target_entity": "BASE:LN-017",
      "at": "mid",
      "position": [
        4300.0,
        7200.0
      ],
      "content": "EP 15' RT",
      "layer": "V-ANNO-TEXT"
    }
  },
  "warnings": []
}

